import{_ as i,o,c as t,a2 as a}from"./chunks/framework.BDCokyix.js";const h=JSON.parse('{"title":"Space Authorization Model","description":"","frontmatter":{},"headers":[],"relativePath":"space-authorization-model.md","filePath":"space-authorization-model.md","lastUpdated":1790074091000}'),s={name:"space-authorization-model.md"};function r(n,e,d,c,l,p){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="space-authorization-model" tabindex="-1">Space Authorization Model <a class="header-anchor" href="#space-authorization-model" aria-label="Permalink to &quot;Space Authorization Model&quot;">​</a></h1><p>This document defines how Soma authorizes reads and writes of space-scoped content (documents, messages, blobs).</p><h2 id="what-counts-as-a-member" tabindex="-1">What counts as a member? <a class="header-anchor" href="#what-counts-as-a-member" aria-label="Permalink to &quot;What counts as a member?&quot;">​</a></h2><p>Possession of a valid <code>MembershipCapability</code> for the target <code>space_id</code>:</p><ul><li>Signed (<code>signed</code> present).</li><li>Subject matches the requester’s libp2p <code>PeerId</code> from the authenticated channel.</li><li>Not expired (<code>expires_at</code> is in the future, if set).</li><li>Issuer is trusted: <ul><li>Issuer is the space owner, <strong>or</strong></li><li>Issuer presents a valid <code>IssuerCapability</code> delegated by the owner for that space.</li></ul></li></ul><h2 id="invariant-all-space-reads-require-membership" tabindex="-1">Invariant: all space reads require membership <a class="header-anchor" href="#invariant-all-space-reads-require-membership" aria-label="Permalink to &quot;Invariant: all space reads require membership&quot;">​</a></h2><p>Every surface that returns space content must check membership:</p><ul><li>libp2p request/response (<code>/soma/blob/1</code> and any future protocols).</li><li>In-process daemon surface exposed to the renderer via the Tauri host (<code>desktop-api</code> handlers → <code>desktop-commands</code> → <code>@soma/sdk</code>).</li><li><code>somad bot</code> admin HTTP (if it ever exposes read APIs).</li></ul><p>Controllers are thin; the check should live in the service layer so all surfaces reuse it.</p><h2 id="where-membership-is-enforced-today" tabindex="-1">Where membership is enforced today <a class="header-anchor" href="#where-membership-is-enforced-today" aria-label="Permalink to &quot;Where membership is enforced today&quot;">​</a></h2><ul><li>libp2p blobs: blob handler calls <code>SpaceAuthorizer</code> before serving bytes.</li><li>In-process daemon (via the Tauri command surface): <code>uploadBlob</code>/<code>upsertDocument</code> require membership.</li><li>Space creation: <code>CreateSpace</code> stores owner metadata plus an owner-signed <code>SpaceGenesisArtifact</code>.</li><li>Join decisions: membership capabilities are signature/subject/issuer-checked before persistence; delegated issuer chains are verified when the owner key is known.</li><li>Issuer delegation: <code>IssueIssuerCapability</code> is implemented on the in-process daemon surface, requires the current daemon to own the space, and persists the owner-signed delegation locally.</li><li>Discovery: <code>DiscoverSpaces</code> is implemented as local known-space discovery. It does not query rendezvous metadata yet.</li></ul><h2 id="verification-rules" tabindex="-1">Verification rules <a class="header-anchor" href="#verification-rules" aria-label="Permalink to &quot;Verification rules&quot;">​</a></h2><ul><li>Verify signatures with the signer’s libp2p public key (from Identify).</li><li>Bind <code>subject_peer_id</code> to the remote peer identity (not payload).</li><li>Enforce expiry on membership and issuer capabilities.</li><li>Delegation chain: owner signs issuer cap → issuer signs membership cap.</li><li>Reject signed capability payload mismatches so post-signature field tampering does not persist.</li></ul><h2 id="space-invites" tabindex="-1">Space invites <a class="header-anchor" href="#space-invites" aria-label="Permalink to &quot;Space invites&quot;">​</a></h2><p>A <code>soma://invite/&lt;payload&gt;</code> link is an <strong>owner-signed, self-contained credential</strong> — the mechanism <code>soma_membership::invite</code> implements. It closes part of the TOFU gap described above: without an invite, the <em>only</em> input to a first-contact trust decision is a peer id typed or pasted out of band, with zero cryptographic binding to the space or to whoever handed it out. An invite instead binds <code>(space_id, default_role, expires_at, bootstrap_multiaddrs, issuer)</code> into one owner-signed unit, verifiable <strong>before dialling anyone</strong>.</p><ul><li><strong>Wire format</strong>: CBOR (via <code>ciborium</code>) of the full signed <code>InviteState</code>, base64url-encoded (no padding), as <code>soma://invite/&lt;payload&gt;</code>. See <code>soma_common::invite_link</code> for the exact byte layout.</li><li><strong>Offline verification</strong>: <code>CborSigned.signer_public_key</code> (protobuf-encoded libp2p public key) is embedded directly in the invite — the one signed artifact in this schema that carries its own key, because this deployment&#39;s real identities are ECDSA (<code>soma_net::NetIdentity::generate</code>), whose peer ids do <strong>not</strong> embed the public key the way small Ed25519 keys can. Every other signed artifact (<code>MembershipCapability</code>, <code>IssuerCapability</code>, <code>SpaceGenesisArtifact</code>) is still verified exclusively through <code>PeerKeyResolver</code>/<code>TrustAnchor</code> against a locally-pinned key — <code>signer_public_key</code> is populated only for <code>InviteState</code> and must never be read by any other verifier. See <code>soma_common::verify_invite_state</code>&#39;s doc comment for the precise, narrow claim this embedding does and doesn&#39;t prove.</li><li><strong>Redemption pins the trust anchor</strong>: <code>soma_membership::invite::redeem_invite</code> routes the verified issuer through the exact same <code>resolve_trust_anchor</code> / <code>pin_trust_anchor</code> primitives as every other first-contact path (never a parallel mechanism), and caches the issuer&#39;s verified public key into <code>peer_public_keys</code> so a later inbound <code>JoinDecision</code> can be signature-checked without waiting on a separate Identify exchange.</li><li><strong>What is still TOFU</strong>: the <em>first</em> time a device sees a given space, trusting that a particular invite link genuinely came from the expected owner is inherent to any invite-link system (Slack/Discord/Docs share links have the same property) — the improvement is that tampering with the link&#39;s terms in transit, or a MITM substituting a different issuer/role, breaks the signature and is rejected before any network contact, rather than being undetectable the way a bare pasted peer id is.</li><li><strong>Replay protection</strong>: issued invites and per-invite redemption counts are persisted (<code>invites</code> table / <code>soma_storage::invites::InviteRepository</code>); <code>try_consume</code> is a single guarded <code>UPDATE</code> so a single-use invite (the default) cannot be redeemed twice even under concurrent attempts. Decider-side auto-approval (<code>join_decider::storage</code>) trusts only its own previously-inserted <code>invites</code> row, looked up by nonce — never wire-provided invite fields — matching the same &quot;local ground truth only&quot; pattern as bot self-recruitment.</li></ul><h2 id="notes-and-gaps" tabindex="-1">Notes and gaps <a class="header-anchor" href="#notes-and-gaps" aria-label="Permalink to &quot;Notes and gaps&quot;">​</a></h2><ul><li>Owner public key discovery is required to validate delegations where owner ≠ sender.</li><li>The signing payload uses the current CBOR view helpers; canonical CBOR remains a cross-version interoperability task.</li><li>UI guardrails should redirect non-members from space routes, but the backend is the security boundary.</li><li>Future work: revocation + key rotation, and optional end-to-end encryption by space.</li><li>Invite <code>InviteProof</code> requester signatures are built (<code>soma_common::build_invite_proof</code>) but not yet verified server-side against the requester&#39;s own key — doing so needs the requester&#39;s public key, which this crate only ever sources from a prior Identify exchange (<code>PeerKeyResolver</code>), and nothing currently guarantees Identify completes before a <code>JoinRequest</code> arrives on a freshly-dialled connection. Auto-approval instead relies entirely on the decider&#39;s own locally-issued <code>invites</code> row (space match via the composite key, expiry, single-use nonce) — see <code>soma_membership::invite</code>&#39;s module doc comment.</li></ul><h2 id="terminology-note" tabindex="-1">Terminology note <a class="header-anchor" href="#terminology-note" aria-label="Permalink to &quot;Terminology note&quot;">​</a></h2><ul><li><code>Owner</code>, <code>Editor</code>, <code>Viewer</code>, <code>Member</code>, and <code>Bot</code> are workspace access roles.</li><li>Bot operating mode like <code>admin</code> is deployment/runtime terminology, not a human workspace role.</li><li>Local AI model feature hints in the desktop UI are not security capabilities and do not grant access.</li><li>A delegated approver is a separate authority concept. A bot may be a delegated approver, but the <code>Bot</code> role alone does not imply join approval powers.</li></ul>',20)])])}const m=i(s,[["render",r]]);export{h as __pageData,m as default};
